#!/usr/bin/env bash
# ops/batch_p07c_api_service.sh
#
# Final batch of P0.7 - wires the new `api` service (core/'s FastAPI
# channel-lifecycle backend) into docker-compose.yml and .env.example.
# Built on top of Batch B (batch_p07b_channels_and_reconnect.sh, already
# applied - core/ must already exist with routes_channels.py etc).
#
# Four pieces, applied in order, each backing up what it overwrites:
#
#   1. core/Dockerfile (new file). NOT build-verified in the sandbox this
#      was generated in (Docker Hub pulls are policy-blocked there - the
#      base image `FROM python:3.12.8-slim` line itself could not be
#      resolved). Syntactically valid. YOU must run
#      `docker compose build api` for real after applying this script, and
#      treat that as part of closing this batch, not optional.
#
#   2. docker-compose.yml - full overwrite (backed up first). Adds exactly
#      one new service (`api`) and updates one comment line above
#      `prometheus`; every other line reproduces your real file verbatim
#      (verified this session via a literal diff against your own pasted
#      content - zero unintended changes).
#
#   3. .env.example - full overwrite (backed up first). Adds METRICS_TOKEN
#      (closes a pre-existing gap - see docs/P0_FINDINGS.md F16 /
#      docs/P0_DEVIATIONS.md D-27: docker-compose.yml already required it,
#      .env.example never listed it) and a new "Core P0.7 API" section.
#      Every other line reproduces your real file verbatim.
#
#   4. docs/P0_DEVIATIONS.md - guarded append of D-32 (role reuse, PgBouncer
#      routing split, the libpq key=value DSN decision + its empirical
#      special-character test, the METRICS_TOKEN gap closure, port 8080, and
#      the deliberate Prometheus-scrape deferral).
#
# This script NEVER runs `git commit`. Review the diff, then commit yourself
# (Gate A) - exactly like every batch before it.
set -euo pipefail

REPO_ROOT="$(git rev-parse --show-toplevel 2>/dev/null || true)"
if [ -z "$REPO_ROOT" ]; then
  echo "error: not inside a git repository. cd into the sharwa_ai repo root first." >&2
  exit 1
fi
if [ ! -d "$REPO_ROOT/core" ] || [ ! -f "$REPO_ROOT/docker-compose.yml" ] || [ ! -f "$REPO_ROOT/.env.example" ]; then
  echo "error: $REPO_ROOT doesn't look like the sharwa_ai repo root, or Batch B hasn't been applied yet (no core/)." >&2
  exit 1
fi
cd "$REPO_ROOT"

TS="$(date +%Y%m%d%H%M%S)"

echo "== [1/4] core/Dockerfile (new) =="
if [ -f core/Dockerfile ]; then
  backup="core/Dockerfile.bak-${TS}"
  cp core/Dockerfile "$backup"
  echo "  backed up existing core/Dockerfile -> $backup"
fi
DOCKERFILE_B64=''
echo "$DOCKERFILE_B64" | base64 -d > core/Dockerfile
echo "  wrote core/Dockerfile"

echo
echo "== [2/4] docker-compose.yml (full overwrite, backed up first) =="
backup="docker-compose.yml.bak-${TS}"
cp docker-compose.yml "$backup"
echo "  backed up existing docker-compose.yml -> $backup"
COMPOSE_B64=''
echo "$COMPOSE_B64" | base64 -d > docker-compose.yml
echo "  wrote docker-compose.yml"

echo
echo "== [3/4] .env.example (full overwrite, backed up first) =="
backup=".env.example.bak-${TS}"
cp .env.example "$backup"
echo "  backed up existing .env.example -> $backup"
ENV_EXAMPLE_B64=''
echo "$ENV_EXAMPLE_B64" | base64 -d > .env.example
echo "  wrote .env.example"

echo
echo "== [4/4] docs/P0_DEVIATIONS.md: guarded append of D-32 =="

append_guarded() {
  local file="$1" anchor="$2" newblock_b64="$3" label="$4"
  if [ ! -f "$file" ]; then
    echo "  error: $file does not exist - cannot guard-append. Skipping (apply by hand)." >&2
    return 1
  fi
  if ! grep -qF "$anchor" "$file"; then
    echo "  error: $label - the expected anchor text (end of D-31, the last" >&2
    echo "         entry this session knew about) was not found verbatim in" >&2
    echo "         your real $file. Your file has diverged from this" >&2
    echo "         sandbox's reconstruction - nothing was written. Merge the" >&2
    echo "         new section by hand; it is saved at:" >&2
    echo "         /tmp/$(basename "$file").p07c_new_section for you to paste in." >&2
    echo "$newblock_b64" | base64 -d > "/tmp/$(basename "$file").p07c_new_section"
    return 1
  fi
  if grep -qF "## D-32" "$file" 2>/dev/null; then
    echo "  skipping $file - it already contains D-32 (already applied?)." >&2
    return 0
  fi
  echo "$newblock_b64" | base64 -d >> "$file"
  echo "  appended D-32 to $file"
}

DEVIATIONS_NEW_B64=''
DEVIATIONS_ANCHOR='تُرك بلا تغيير، وموثَّق هنا كبند مفتوح منفصل.'

append_guarded "docs/P0_DEVIATIONS.md" "$DEVIATIONS_ANCHOR" "$DEVIATIONS_NEW_B64" "docs/P0_DEVIATIONS.md (D-32)" || true

echo
cat <<'EOF'
================================================================================
Batch C (final, P0.7) delivered: core/Dockerfile, docker-compose.yml (+ `api`
service), .env.example (+ METRICS_TOKEN + Core P0.7 API section), and the
D-32 documentation entry (or a clear abort + saved section if your real
docs/P0_DEVIATIONS.md had diverged - check for any "error:" lines above).

Nothing has been committed. Next steps:

  1) Review the diff:
       git status
       git diff -- docker-compose.yml .env.example core/Dockerfile docs/P0_DEVIATIONS.md

  2) Fill in the real secrets in your actual .env (NOT .env.example):
       JWT_ISSUER, JWT_AUDIENCE, JWKS_URL (or JWT_PUBLIC_KEY_PEM), SSO_LOGIN_URL
     METRICS_TOKEN must match whatever gateway/gateway-forwarder already use.

  3) Build the image for real (NOT build-verified in the sandbox this script
     came from - Docker Hub pulls are policy-blocked there):
       docker compose build api

  4) Run the one-time migration adoption step (never auto-run by the image):
       docker compose run --rm api python -m app.cli migrate --adopt-existing-schema 0001_baseline

  5) Bring it up and smoke-test:
       docker compose up -d api
       curl -s http://127.0.0.1:8080/healthz
       curl -s http://127.0.0.1:8080/readyz

  6) Only after a real, successful build + migrate + healthz/readyz on your
     own infra: git commit (Gate A - your explicit, separate step, never
     this script's).

Deliberately deferred, not in this batch: wiring `api:8080` as a new
Prometheus scrape target in ops/prometheus/prometheus.yml (no verified-fresh
copy of that file was available this session either - see the comment left
in docker-compose.yml above the `prometheus` service, and D-32).
================================================================================
EOF
